/*
 * A098933  Primes of the form p+14, where p is a prime.
 * https://oeis.org/A098933
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 17, u16 n <= 53, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence generated by brute‑force search: 
   find the n-th prime q such that (q-14) is also prime. 
   Use the provided big–int primality test. */

#include "../utils/is_prime_big.h"

seq_t a(idx_t n) {
    const seq_t DELTA = (seq_t)14;
    seq_t cand = (seq_t)17;
    idx_t found = 0;

    /* Scan only odd numbers greater than 14. */
    while (found < n) {
        if (is_prime_big(cand) && is_prime_big(cand - DELTA)) {
            ++found;
            if (found == n) {
                return cand;
            }
        }
        cand += (seq_t)2;  /* next odd candidate */
    }

    /* Should never reach here for valid n ≥ 1. */
    return (seq_t)0;
}
